package com.smartspend.ai; import java.util.*;
public class RuleBasedAIService implements AIService {public List<FinancialInsight> generate(InsightContext c){List<FinancialInsight>x=new ArrayList<>();if(c.income()>0&&c.expense()>0)x.add(new SpendingInsight("Your largest expense category is "+c.topCategory()+" at ₹"+String.format("%,.0f",c.topCategoryAmount())+"."));if(c.savingsRate()<20)x.add(new SavingsInsight("Your current savings rate is "+String.format("%.1f",c.savingsRate())+"%. A small recurring reduction in discretionary spending could improve it."));else x.add(new SavingsInsight("Your savings rate is "+String.format("%.1f",c.savingsRate())+"%. Keep tracking monthly goals to maintain this progress."));if(c.budgetUse()>=90)x.add(new BudgetInsight("You have used "+String.format("%.0f",c.budgetUse())+"% of the tracked budget."));else if(c.predictedExpense()>c.expense())x.add(new SpendingInsight("The month-end projection is ₹"+String.format("%,.0f",c.predictedExpense())+" using a transparent daily-spend projection."));return x;}}
